DO $$
BEGIN
  UPDATE subscribers SET tier = 'platinum' WHERE months_active >= 24;
  UPDATE subscribers SET tier = 'gold' WHERE months_active >= 12 AND months_active < 24;
  UPDATE subscribers SET tier = 'silver' WHERE months_active >= 6 AND months_active < 12;
  UPDATE subscribers SET renewal_credit = COALESCE(lifetime_revenue, 0) * 0.10 WHERE tier = 'platinum';
  UPDATE subscribers SET renewal_credit = COALESCE(lifetime_revenue, 0) * 0.05 WHERE tier = 'gold';
END $$;

